<?php
declare(strict_types=1);
require_once __DIR__ . '/../functions/helpers.php';
require_role('customer');
$cart=$_SESSION['cart']??[]; if(!$cart){ set_flash('error','Your bag is empty.'); redirect('customer/cart.php'); }
$ids=array_keys($cart); $placeholders=implode(',',array_fill(0,count($ids),'?')); $stmt=db()->prepare("SELECT p.id,p.name,p.price,p.stock,p.image FROM products p WHERE p.is_active=1 AND p.id IN ($placeholders)");$stmt->execute(array_map('intval',$ids));$products=[];foreach($stmt->fetchAll() as $row){ $products[(int)$row['id']]=$row; }
$subtotal=0;$items=[];foreach($cart as $id=>$qty){$id=(int)$id;$qty=(int)$qty;if(isset($products[$id])&&$qty>0){$qty=min($qty,(int)$products[$id]['stock']);$sub=(float)$products[$id]['price']*$qty;$subtotal+=$sub;$items[]=['id'=>$id,'name'=>$products[$id]['name'],'qty'=>$qty,'price'=>(float)$products[$id]['price'],'subtotal'=>$sub];}}
$shipping=$subtotal>=2500?0:150;$total=$subtotal+$shipping;
$stmt=db()->prepare('SELECT u.name,p.phone,p.address_line1,p.address_line2,p.city,p.province,p.postal_code,p.country FROM users u LEFT JOIN profiles p ON p.user_id=u.id WHERE u.id=?');$stmt->execute([$_SESSION['user_id']]);$profile=$stmt->fetch()?:[]; $errors=$_SESSION['checkout_errors']??[]; $old=$_SESSION['checkout_old']??$profile; unset($_SESSION['checkout_errors'],$_SESSION['checkout_old']);
?><!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1.0"><title>Checkout | Gonzaga's Apparel</title><link rel="stylesheet" href="../css/style.css"><link rel="stylesheet" href="../css/auth.css"></head><body class="shop-page"><header class="mini-header"><a href="../index.php"><img src="../assets/images/logo-placeholder.svg" alt="Gonzaga's Apparel"></a><nav><a href="cart.php">BAG (<?=cart_count()?>)</a><a href="profile.php">PROFILE</a><form action="../logout.php" method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><button type="submit">LOG OUT</button></form></nav></header><main class="shop-shell checkout-shell"><div class="section-kicker">CHECKOUT <span></span></div><h1>COMPLETE YOUR ORDER</h1><?php if($errors):?><div class="alert error"><ul><?php foreach($errors as $error):?><li><?=e($error)?></li><?php endforeach;?></ul></div><?php endif;?><div class="checkout-layout"><form class="auth-form" action="../actions/checkout_process.php" method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><h2>SHIPPING DETAILS</h2><label>FULL NAME</label><input name="name" value="<?=e($old['name']??'')?>" required><label>PHONE</label><input name="phone" value="<?=e($old['phone']??'')?>" required><label>ADDRESS LINE 1</label><input name="address_line1" value="<?=e($old['address_line1']??'')?>" required><label>ADDRESS LINE 2</label><input name="address_line2" value="<?=e($old['address_line2']??'')?>"><div class="form-grid"><div><label>CITY</label><input name="city" value="<?=e($old['city']??'')?>" required></div><div><label>PROVINCE</label><input name="province" value="<?=e($old['province']??'')?>" required></div></div><div class="form-grid"><div><label>POSTAL CODE</label><input name="postal_code" value="<?=e($old['postal_code']??'')?>" required></div><div><label>COUNTRY</label><input name="country" value="<?=e($old['country']??'Philippines')?>" required></div></div><label>PAYMENT METHOD</label><select name="payment_method" required><option value="cod">Cash on Delivery</option><option value="bank_transfer">Bank Transfer</option></select><label>ORDER NOTES (OPTIONAL)</label><textarea name="notes" rows="4" maxlength="500" placeholder="Delivery instructions..."></textarea><button class="button button--filled" type="submit">CONFIRM ORDER · <?=money($total)?></button></form><aside class="checkout-summary"><h2>ORDER SUMMARY</h2><?php foreach($items as $item):?><div class="summary-row"><span><?=e($item['name'])?> × <?=intval($item['qty'])?></span><strong><?=money($item['subtotal'])?></strong></div><?php endforeach;?><div class="summary-row"><span>Subtotal</span><strong><?=money($subtotal)?></strong></div><div class="summary-row"><span>Shipping</span><strong><?=$shipping===0?'FREE':money($shipping)?></strong></div><div class="summary-total"><span>Total</span><strong><?=money($total)?></strong></div><p class="checkout-note">Free shipping on orders of ₱2,500 or more.</p></aside></div></main></body></html>
